77	public class DatanodeHttpServer implements Closeable {
78	  static final Logger LOG = LoggerFactory.getLogger(DatanodeHttpServer.class);
79	  // HttpServer threads are only used for the web UI and basic servlets, so
80	  // set them to the minimum possible
81	  private static final int HTTP_SELECTOR_THREADS = 1;
82	  private static final int HTTP_ACCEPTOR_THREADS = 1;
83	  // Jetty 9.4.x: Adding one more thread to HTTP_MAX_THREADS.
84	  private static final int HTTP_MAX_THREADS =
85	      HTTP_SELECTOR_THREADS + HTTP_ACCEPTOR_THREADS + 2;
86	  private final HttpServer2 infoServer;
87	  private final EventLoopGroup bossGroup;
88	  private final EventLoopGroup workerGroup;
89	  private final ServerSocketChannel externalHttpChannel;
90	  private final ServerBootstrap httpServer;
91	  private final SSLFactory sslFactory;
92	  private final ServerBootstrap httpsServer;
93	  private final Configuration conf;
94	  private final Configuration confForCreate;
95	  private InetSocketAddress httpAddress;
96	  private InetSocketAddress httpsAddress;
97	
98	  public DatanodeHttpServer(final Configuration conf,
99	        final DataNode datanode,
100	        final ServerSocketChannel externalHttpChannel)
101	        throws IOException {
102	    this.conf = conf;
103	
104	    Configuration confForInfoServer = new Configuration(conf);
105	    confForInfoServer.setInt(HttpServer2.HTTP_MAX_THREADS_KEY,
106	        HTTP_MAX_THREADS);
107	    confForInfoServer.setInt(HttpServer2.HTTP_SELECTOR_COUNT_KEY,
108	        HTTP_SELECTOR_THREADS);
109	    confForInfoServer.setInt(HttpServer2.HTTP_ACCEPTOR_COUNT_KEY,
110	        HTTP_ACCEPTOR_THREADS);
111	    int proxyPort =
112	        confForInfoServer.getInt(DFS_DATANODE_HTTP_INTERNAL_PROXY_PORT, 0);
113	    HttpServer2.Builder builder = new HttpServer2.Builder()
114	        .setName("datanode")
115	        .setConf(confForInfoServer)
116	        .setACL(new AccessControlList(conf.get(DFS_ADMIN, " ")))
117	        .hostName(getHostnameForSpnegoPrincipal(confForInfoServer))
118	        .addEndpoint(URI.create("http://localhost:" + proxyPort))
119	        .setFindPort(true);
120	
121	    final boolean xFrameEnabled = conf.getBoolean(
122	        DFSConfigKeys.DFS_XFRAME_OPTION_ENABLED,
123	        DFSConfigKeys.DFS_XFRAME_OPTION_ENABLED_DEFAULT);
124	
125	    final String xFrameOptionValue = conf.getTrimmed(
126	        DFSConfigKeys.DFS_XFRAME_OPTION_VALUE,
127	        DFSConfigKeys.DFS_XFRAME_OPTION_VALUE_DEFAULT);
128	
129	    builder.configureXFrame(xFrameEnabled).setXFrameOption(xFrameOptionValue);
130	
131	    this.infoServer = builder.build();
132	
133	    this.infoServer.setAttribute(HttpServer2.CONF_CONTEXT_ATTRIBUTE, conf);
134	    this.infoServer.setAttribute("datanode", datanode);
135	    this.infoServer.setAttribute(JspHelper.CURRENT_CONF, conf);
136	    this.infoServer.addServlet(null, "/blockScannerReport",
137	        BlockScanner.Servlet.class);
138	    DataNodeUGIProvider.init(conf);
139	    this.infoServer.start();
140	    final InetSocketAddress jettyAddr = infoServer.getConnectorAddress(0);
141	
142	    this.confForCreate = new Configuration(conf);
143	    confForCreate.set(FsPermission.UMASK_LABEL, "000");
144	
145	    this.bossGroup = new NioEventLoopGroup();
146	    this.workerGroup = new NioEventLoopGroup();
147	    this.externalHttpChannel = externalHttpChannel;
148	    HttpConfig.Policy policy = DFSUtil.getHttpPolicy(conf);
149	    final ChannelHandler[] handlers = getFilterHandlers(conf);
150	
151	    if (policy.isHttpEnabled()) {
152	      this.httpServer = new ServerBootstrap().group(bossGroup, workerGroup)
153	            .childHandler(new ChannelInitializer<SocketChannel>() {
154	              @Override
155	              protected void initChannel(SocketChannel ch) throws Exception {
156	                ChannelPipeline p = ch.pipeline();
157	                p.addLast(new HttpRequestDecoder(),
158	                    new HttpResponseEncoder());
159	                if (handlers != null) {
160	                  for (ChannelHandler c : handlers) {
161	                    p.addLast(c);
162	                  }
163	                }
164	                p.addLast(
165	                    new ChunkedWriteHandler(),
166	                    new URLDispatcher(jettyAddr, conf, confForCreate));
167	              }
168	            });
169	
170	      this.httpServer.childOption(
171	          ChannelOption.WRITE_BUFFER_HIGH_WATER_MARK,
172	          conf.getInt(
173	              DFSConfigKeys.DFS_WEBHDFS_NETTY_HIGH_WATERMARK,
174	              DFSConfigKeys.DFS_WEBHDFS_NETTY_HIGH_WATERMARK_DEFAULT));
175	      this.httpServer.childOption(
176	          ChannelOption.WRITE_BUFFER_LOW_WATER_MARK,
177	          conf.getInt(
178	              DFSConfigKeys.DFS_WEBHDFS_NETTY_LOW_WATERMARK,
179	              DFSConfigKeys.DFS_WEBHDFS_NETTY_LOW_WATERMARK_DEFAULT));
180	
181	      if (externalHttpChannel == null) {
182	        httpServer.channel(NioServerSocketChannel.class);
183	      } else {
184	        httpServer.channelFactory(new ChannelFactory<NioServerSocketChannel>() {
185	          @Override
186	          public NioServerSocketChannel newChannel() {
187	            return new NioServerSocketChannel(externalHttpChannel) {
188	              // The channel has been bounded externally via JSVC,
189	              // thus bind() becomes a no-op.
190	              @Override
191	              protected void doBind(SocketAddress localAddress)
192	                  throws Exception {
193	              }
194	            };
195	          }
196	        });
197	      }
198	    } else {
199	      this.httpServer = null;
200	    }

